using System;using System.IO;using System.Reflection;using System.Runtime.CompilerServices;using System.Threading;using Newtonsoft.Json.Linq;using TopoptLab.GH;
class EngineeringSmoke {
 static int Main(string[] args){string[] paths={args[0],args[1],args[2]};AppDomain.CurrentDomain.AssemblyResolve+=delegate(object sender,ResolveEventArgs e){foreach(string p in paths)foreach(string ext in new[]{".dll",".gha"}){string f=Path.Combine(p,new AssemblyName(e.Name).Name+ext);if(File.Exists(f))return Assembly.LoadFrom(f);}return null;};try{Test(args[3],args[4]);return 0;}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 [MethodImpl(MethodImplOptions.NoInlining)]static void Test(string fixture,string config){var request=JObject.Parse(File.ReadAllText(fixture));var job=WorkerJob.Start(request,WorkerJob.Hash(request.ToString()),config);var deadline=DateTime.UtcNow.AddSeconds(60);while(job.Running&&DateTime.UtcNow<deadline)Thread.Sleep(50);if(job.Running){job.Cancel();throw new Exception("Timeout");}var result=job.Snapshot();if(result==null||(string)result["status"]!="completed")throw new Exception("Engineering worker failed: "+job.Folder+" "+result);if(!File.Exists(Path.Combine(job.Folder,"report.html")))throw new Exception("Missing report");if(((JArray)result["engineering"]["cases"]).Count!=2)throw new Exception("Lost load case");Console.WriteLine("Engineering C#/Python bridge passed: "+job.Folder);}
}
